(1617145, 216720, 40338, '<td valign="top">awesome, love it</td>', 'awesome, love it', '2005-08-17 07:55:20.000000', NULL, 1),
(1617147, 218382, 8522, '<td valign="top">Very nice, love the use of wide angle. Background is nice and simple. Good colour balance. Very competent indeed, but missing an extra something... I wish the bass player was a tad more dynamic.</td>', 'Very nice, love the use of wide angle. Background is nice and simple. Good colour balance. Very competent indeed, but missing an extra something... I wish the bass player was a tad more dynamic.', '2005-08-17 07:55:41.000000', NULL, 1),
(1617149, 218428, 40338, '<td valign="top">hmmm..i''d say noise rather than music, but a very nice picture - know it''s very difficult to get the plane in the pic where you want it, so well done</td>', 'hmmm..i''d say noise rather than music, but a very nice picture - know it''s very difficult to get the plane in the pic where you want it, so well done', '2005-08-17 07:56:31.000000', NULL, 1),
