(1618208, 218324, 37444, '<td valign="top">There is a story in his eyes - just wonderful. 10</td>', 'There is a story in his eyes - just wonderful. 10', '2005-08-17 13:03:49.000000', NULL, 1),
(1618212, 218968, 9690, '<td valign="top">Hmmm... lighting is a bit dull, and everything is soft.  I understand the motion capture, but its all a bit soft.</td>', 'Hmmm... lighting is a bit dull, and everything is soft.  I understand the motion capture, but its all a bit soft.', '2005-08-17 13:04:16.000000', NULL, 1),
