(1624577, 218798, 40797, '<td valign="top">Nice clear picture.</td>', 'Nice clear picture.', '2005-08-19 19:17:12.000000', NULL, 1),
(1624581, 218972, 40797, '<td valign="top">I l like the setting and expression on your subjects face. I do not know how I feel about the lighting on the guitar.</td>', 'I l like the setting and expression on your subjects face. I do not know how I feel about the lighting on the guitar.', '2005-08-19 19:20:20.000000', NULL, 1),
