INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1626026, 216232, 9906, '<td valign="top">Your focus is a little soft.  I don''t mind that so much, however you are also blwon out in the highlights and the guys head dissappears into the pier...  Taking a shot that isn''t exposed properly and turning it b/w will usually only accentuate the fact that it''s not exposed properly...<br/>TC</td>', 'Your focus is a little soft.  I don''t mind that so much, however you are also blwon out in the highlights and the guys head dissappears into the pier...  Taking a shot that isn''t exposed properly and turning it b/w will usually only accentuate the fact that it''s not exposed properly...TC', '2005-08-20 11:18:15.000000', NULL, 1),
