INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1635619, 218960, 40370, '<td valign="top">Would have liked the strings in focus as they are the delicate, detailed part of this composition, nice lighting and golden color.</td>', 'Would have liked the strings in focus as they are the delicate, detailed part of this composition, nice lighting and golden color.', '2005-08-23 12:57:42.000000', NULL, 1),
(1635622, 218324, 40370, '<td valign="top">Do those eyes tell the story of a lifetime or what? Good capture, nice focus on the subject and appropriately blurry background.</td>', 'Do those eyes tell the story of a lifetime or what? Good capture, nice focus on the subject and appropriately blurry background.', '2005-08-23 13:00:09.000000', NULL, 1),
(1635627, 218025, 40370, '<td valign="top">Unique idea for subject behind the scenes, IMO better focus and less red would have improved the pic.</td>', 'Unique idea for subject behind the scenes, IMO better focus and less red would have improved the pic.', '2005-08-23 13:02:04.000000', NULL, 1),
(1635632, 217867, 40370, '<td valign="top">I like the crop and composition, what a cute nose !!</td>', 'I like the crop and composition, what a cute nose !!', '2005-08-23 13:03:30.000000', NULL, 1),
(1635653, 217943, 40370, '<td valign="top">What a face, many years of performing in those wrinkles, great close-up, front row seats?</td>', 'What a face, many years of performing in those wrinkles, great close-up, front row seats?', '2005-08-23 13:08:15.000000', NULL, 1),
